def transform2(g, dbg=False):
    from collections import deque
    h,w=len(g),len(g[0]); bg=g[0][0]
    seen=[[False]*w for _ in range(h)]; q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True;q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True;q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and g[a][b]==bg and not seen[a][b]: seen[a][b]=True;q.append((a,b))
    comp=[[-1]*w for _ in range(h)]; n=0
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and not seen[i][j] and comp[i][j]<0:
                q.append((i,j)); comp[i][j]=n
                while q:
                    a,b=q.popleft()
                    for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+di,b+dj
                        if 0<=x<h and 0<=y<w and g[x][y]==bg and not seen[x][y] and comp[x][y]<0:
                            comp[x][y]=n;q.append((x,y))
                n+=1
    sizes=[sum(1 for i in range(h) for j in range(w) if comp[i][j]==c) for c in range(n)]
    if dbg: print(n,sizes)
    out=[r[:] for r in g]
    for i in range(h):
        for j in range(w):
            if comp[i][j]>=0: out[i][j]=7 if sizes[comp[i][j]]==1 else 2
    return out
